use std::io::Read;

fn main() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let (first, rest) = match s.find('\n') {
        Some(i) => (&s[..i], &s[i + 1..]),
        None => (&s[..], ""),
    };
    let t = first.trim();
    let ok = !t.is_empty() && t.chars().all(|c| c.is_ascii_digit()) && t.chars().any(|c| c != '0');
    if !ok {
        println!("error: bad width");
        std::process::exit(1);
    }
    let w: usize = t.parse().unwrap_or(usize::MAX);
    let mut out = String::new();
    let mut line = String::new();
    let mut len = 0usize;
    for word in rest.split_whitespace() {
        let wl = word.chars().count();
        if len == 0 {
            line.push_str(word);
            len = wl;
        } else if len.saturating_add(1).saturating_add(wl) <= w {
            line.push(' ');
            line.push_str(word);
            len += 1 + wl;
        } else {
            out.push_str(&line);
            out.push('\n');
            line = word.to_string();
            len = wl;
        }
    }
    if len > 0 {
        out.push_str(&line);
        out.push('\n');
    }
    print!("{}", out);
}

